CREATE TABLE IF NOT EXISTS instance_metadata (singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton), schema_version integer NOT NULL, epoch text NOT NULL);
CREATE TABLE IF NOT EXISTS instance_tokens (id text PRIMARY KEY, secret_hash bytea NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz);
CREATE TABLE IF NOT EXISTS projects (id text PRIMARY KEY, name text NOT NULL, revision bigint NOT NULL DEFAULT 0, event_floor_revision bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE IF NOT EXISTS principals (project_id text REFERENCES projects(id), id text NOT NULL, display_name text NOT NULL, PRIMARY KEY(project_id,id));
CREATE TABLE IF NOT EXISTS tokens (id text PRIMARY KEY, project_id text NOT NULL REFERENCES projects(id), principal_id text NOT NULL, secret_hash bytea NOT NULL, role text NOT NULL CHECK(role IN ('viewer','editor','coordinator','project_admin')), expires_at timestamptz NOT NULL, revoked_at timestamptz, FOREIGN KEY(project_id,principal_id) REFERENCES principals(project_id,id));
CREATE TABLE IF NOT EXISTS contexts (project_id text REFERENCES projects(id), id text NOT NULL, kind text NOT NULL CHECK(kind IN ('state','plan','observation','decision','handoff')), current_version bigint NOT NULL, archived boolean NOT NULL DEFAULT false, PRIMARY KEY(project_id,id));
CREATE TABLE IF NOT EXISTS context_versions (project_id text NOT NULL, context_id text NOT NULL, version bigint NOT NULL, document jsonb NOT NULL, recorded_by text NOT NULL, revision bigint NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), PRIMARY KEY(project_id,context_id,version), FOREIGN KEY(project_id,context_id) REFERENCES contexts(project_id,id), FOREIGN KEY(project_id,recorded_by) REFERENCES principals(project_id,id));
CREATE TABLE IF NOT EXISTS context_links (project_id text NOT NULL, source_id text NOT NULL, source_version bigint NOT NULL, target_id text NOT NULL, target_version bigint NOT NULL, PRIMARY KEY(project_id,source_id,source_version,target_id,target_version), FOREIGN KEY(project_id,source_id,source_version) REFERENCES context_versions(project_id,context_id,version), FOREIGN KEY(project_id,target_id,target_version) REFERENCES context_versions(project_id,context_id,version));
CREATE TABLE IF NOT EXISTS state_pins (project_id text NOT NULL, name text NOT NULL, context_id text NOT NULL, context_version bigint NOT NULL, version bigint NOT NULL, PRIMARY KEY(project_id,name), FOREIGN KEY(project_id,context_id,context_version) REFERENCES context_versions(project_id,context_id,version));
CREATE TABLE IF NOT EXISTS tasks (project_id text REFERENCES projects(id), id text NOT NULL, title text NOT NULL, acceptance text NOT NULL, state text NOT NULL CHECK(state IN ('todo','doing','done','cancelled')), version bigint NOT NULL DEFAULT 1, owner_id text, lease_generation bigint NOT NULL DEFAULT 0, lease_hash bytea, lease_expires_at timestamptz, progress jsonb NOT NULL DEFAULT '{}', PRIMARY KEY(project_id,id), FOREIGN KEY(project_id,owner_id) REFERENCES principals(project_id,id));
CREATE TABLE IF NOT EXISTS task_dependencies (project_id text NOT NULL, task_id text NOT NULL, depends_on_id text NOT NULL, PRIMARY KEY(project_id,task_id,depends_on_id), CHECK(task_id<>depends_on_id), FOREIGN KEY(project_id,task_id) REFERENCES tasks(project_id,id), FOREIGN KEY(project_id,depends_on_id) REFERENCES tasks(project_id,id));
CREATE TABLE IF NOT EXISTS context_tasks (project_id text NOT NULL, context_id text NOT NULL, version bigint NOT NULL, task_id text NOT NULL, PRIMARY KEY(project_id,context_id,version,task_id), FOREIGN KEY(project_id,context_id,version) REFERENCES context_versions(project_id,context_id,version), FOREIGN KEY(project_id,task_id) REFERENCES tasks(project_id,id));
CREATE TABLE IF NOT EXISTS blockers (project_id text NOT NULL, id text NOT NULL, task_id text NOT NULL, reason text NOT NULL, owner_id text NOT NULL, check_after timestamptz NOT NULL, resolved_at timestamptz, resolution_context_id text, resolution_version bigint, PRIMARY KEY(project_id,id), FOREIGN KEY(project_id,task_id) REFERENCES tasks(project_id,id), FOREIGN KEY(project_id,owner_id) REFERENCES principals(project_id,id), FOREIGN KEY(project_id,resolution_context_id,resolution_version) REFERENCES context_versions(project_id,context_id,version));
CREATE TABLE IF NOT EXISTS resource_leases (project_id text REFERENCES projects(id), name text NOT NULL, version bigint NOT NULL DEFAULT 0, owner_id text, lease_generation bigint NOT NULL DEFAULT 0, lease_hash bytea, lease_expires_at timestamptz, external_job jsonb NOT NULL DEFAULT '{}', PRIMARY KEY(project_id,name), FOREIGN KEY(project_id,owner_id) REFERENCES principals(project_id,id));
CREATE TABLE IF NOT EXISTS project_events (project_id text REFERENCES projects(id), revision bigint NOT NULL, type text NOT NULL, resource_id text NOT NULL, resource_version bigint NOT NULL, actor_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), PRIMARY KEY(project_id,revision));
CREATE TABLE IF NOT EXISTS idempotency_keys (token_id text NOT NULL, key text NOT NULL, request_hash bytea NOT NULL, response_status integer NOT NULL, response_body jsonb NOT NULL, secret boolean NOT NULL DEFAULT false, expires_at timestamptz NOT NULL DEFAULT clock_timestamp()+interval '24 hours', PRIMARY KEY(token_id,key));
CREATE TABLE IF NOT EXISTS audit_entries (id bigserial PRIMARY KEY, project_id text, actor_id text NOT NULL, action text NOT NULL, target text NOT NULL, reason text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE INDEX IF NOT EXISTS event_retention ON project_events(project_id,created_at);
CREATE INDEX IF NOT EXISTS context_document ON context_versions USING gin(document jsonb_path_ops);
